contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token) public {
        require(token != address(0));

        // Read reward data BEFORE the call; addReward(token) is the deciding call.
        (uint40 pfBefore, , uint40 luBefore, ) = c.rewardData(token);

        bool reverted;
        try c.addReward(token) { reverted = false; } catch { reverted = true; }

        // Read reward data AFTER the call.
        (uint40 pfAfter, , uint40 luAfter, ) = c.rewardData(token);

        if (reverted) {
            // Revert happens exactly when the token was already registered.
            assert(luBefore != 0);
        } else {
            // Success happens exactly when the token was not yet registered,
            // and the new data has lastUpdateTime == periodFinish == block.timestamp.
            assert(luBefore == 0);
            assert(luAfter == uint40(block.timestamp));
            assert(pfAfter == uint40(block.timestamp));
        }
    }

    receive() external payable {}
}

