contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 rewardAmount) public payable {
        require(rewardToken != address(0), "zero reward token");
        require(rewardAmount > 0, "zero reward amount");

        c.addReward(rewardToken);

        c.notifyRewardAmount(rewardToken, rewardAmount);

        uint256 totalSupplyBefore = c.totalSupply();
        uint216 rewardPerTokenStoredBefore = uint216(0);
        uint216 rewardRateBefore = uint216(0);
        uint40 lastUpdateTimeBefore = uint40(0);
        uint40 periodFinishBefore = uint40(0);

        // Read observable reward accounting fields before the deciding call.
        (
            uint40 periodFinish,
            uint216 rewardRate,
            uint40 lastUpdateTime,
            uint216 rewardPerTokenStored
        ) = c.rewardData(rewardToken);
        rewardPerTokenStoredBefore = rewardPerTokenStored;
        rewardRateBefore = rewardRate;
        lastUpdateTimeBefore = lastUpdateTime;
        periodFinishBefore = periodFinish;

        uint256 expectedRewardPerToken;
        if (totalSupplyBefore == 0) {
            expectedRewardPerToken = rewardPerTokenStoredBefore;
        } else {
            uint256 applicableTime;
            if (periodFinishBefore < block.timestamp) {
                applicableTime = periodFinishBefore;
            } else {
                applicableTime = block.timestamp;
            }
            if (applicableTime < lastUpdateTimeBefore) {
                applicableTime = lastUpdateTimeBefore;
            }
            uint256 elapsed = applicableTime - lastUpdateTimeBefore;
            expectedRewardPerToken =
                rewardPerTokenStoredBefore +
                ((elapsed * rewardRateBefore * 1e18) / totalSupplyBefore);
        }

        uint256 observedRewardPerToken = c.rewardPerToken(rewardToken);

        assert(observedRewardPerToken == expectedRewardPerToken);
    }

    receive() external payable {}
}

