contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, uint256 amount) public payable {
        require(token != address(0), "token");
        require(amount > 0, "amount");

        bool added;
        try c.addReward(token) {
            added = true;
        } catch {
            added = false;
        }

        uint40 beforeFinish = c.rewardPeriodFinish(token);

        if (!added) {
            assert(beforeFinish == 0);
        } else {
            require(address(this).balance >= amount, "balance");

            c.setRewardDistributor(address(this));

            uint256 balBefore = c.balanceOf(address(this));
            (bool ok, ) = token.call(abi.encodeWithSignature("transfer(address,uint256)", address(c), amount));
            require(ok, "transfer setup failed");

            c.notifyRewardAmount(token, amount);

            bool notifierOk = true;
            try c.notifyRewardAmount(token, amount) {
                notifierOk = true;
            } catch {
                notifierOk = false;
            }

            uint40 afterFinish = c.rewardPeriodFinish(token);

            assert(afterFinish >= uint40(block.timestamp) && afterFinish >= beforeFinish);
        }
    }

    receive() external payable {}
}

