contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 amount) public {
        // Caller of the test contract is the test contract only; to isolate notifyRewardAmount's
        // distributor check we call it directly and observe revert or token balance change.
        // The test contract is deployed by the fresh C deployment, so it is msg.sender for
        // all calls on c. The distributor is set by the external deployer, not this test, so
        // a call by this test contract is expected to revert unless the distributor is this
        // contract (which the checker may or may not set). We still make the call observable.

        // The reward token must be registered via addReward (owner-only) OR unknown. Both cases
        // are driven through the public surface: we must not assume ownership. The only way to
        // register is c.addReward(...), which may revert if caller is not owner. We avoid
        // requiring that call to succeed by not making it the deciding call.

        // Pass all inputs as parameters; amount is a uint256 (may be zero).
        // Attempt the deciding call and record whether it reverted.

        uint256 balBefore = 0;
        if (rewardToken != address(0)) {
            (bool ok, bytes memory data) = rewardToken.call(abi.encodeWithSignature("balanceOf(address)", address(c)));
            if (ok && data.length >= 32) {
                balBefore = abi.decode(data, (uint256));
            }
        }

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = 0;
        if (rewardToken != address(0)) {
            (bool ok2, bytes memory data2) = rewardToken.call(abi.encodeWithSignature("balanceOf(address)", address(c)));
            if (ok2 && data2.length >= 32) {
                balAfter = abi.decode(data2, (uint256));
            }
        }

        // General rule: if notifyRewardAmount did NOT revert and amount was positive and
        // the reward token is a real ERC20 whose balanceOf is observable, then c's balance
        // of the reward token must have increased by exactly `amount`.
        if (!reverted && amount > 0 && rewardToken != address(0)) {
            assert(balAfter >= balBefore && balAfter - balBefore == amount);
        } else {
            // If it reverted, or amount is zero, no rule about token balance is asserted here;
            // ensure the assert is still reached with a non-trivial condition.
            assert(balAfter >= balBefore || rewardToken == address(0) || reverted || amount == 0);
        }
    }

    receive() external payable {}
}

