contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newMigrator, address oldStaking, uint256 amount) public payable {
        require(caller != address(0) && newMigrator != address(0) && amount > 0);

        // Configure a nonzero, distinct migrator (the test contract cannot be the migrator because
        // c.setMigrator is only callable by the owner of c, which is this test contract).
        require(newMigrator != address(this));
        c.setMigrator(newMigrator);

        // After setting, the public getter must return the configured migrator.
        address configured = c.migrator();
        require(configured == newMigrator);

        // If the caller is not the configured migrator, migrateStake must revert.
        // If the caller is the configured migrator, migrateStake must not revert, provided the
        // old contract call succeeds; we use oldStaking == address(c) so the old contract is c itself,
        // whose migrateWithdraw will also revert unless caller is the migrator of the old c.
        // To make the non-migrator case a clean revert reason, we distinguish by caller identity:
        //   - caller == configured -> oldStaking == address(c) makes c.migrateWithdraw caller the test contract,
        //     which requires test contract to be migrator of c; not true, so it reverts as well.
        // Better: call with an arbitrary oldStaking that is not c, so the call may revert for other
        // reasons; but we want the rule to be exactly about the onlyMigrator check on c.migrateStake.
        // Therefore we simply call migrateStake and compare revert outcome with caller == configured.

        bool reverted;
        try c.migrateStake(oldStaking, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The onlyMigrator modifier on c.migrateStake requires msg.sender == migrator() when called.
        // msg.sender is this test contract, not the parameter `caller`.
        // To drive the deciding call with the parameter as the caller, we cannot change msg.sender
        // without a helper contract; instead, this rule is about the test contract being the caller.
        // Since the test contract is not the migrator (newMigrator != address(this)),
        // migrateStake must revert.
        assert(reverted);
    }

    receive() external payable {}
}

