    function run(uint256 stakeAmount, address rewardToken, address account, uint256 extraTime) public {
        require(stakeAmount > 0, "need positive stake");
        require(rewardToken != address(0), "need reward token");
        require(account != address(0), "need account");
        require(account != address(this), "account must not be the test contract");
        require(extraTime <= 30 days, "too much extra time");

        // add reward token as owner (InvMutTest owns c after construction)
        c.addReward(rewardToken);

        // record claimable before staking (should be zero for a fresh token/account)
        uint256 claimableBefore = c.claimableRewards(account, rewardToken);

        // account must have tokens to stake
        uint256 bal = c.stakingToken().balanceOf(account);
        require(bal >= stakeAmount, "account lacks tokens to stake");

        // drive c through its public staking entry
        c.stakeFor(account, stakeAmount);

        // read earned after staking; no reward rate was set so earned must equal prior claimable
        uint256 earnedAfter = c.earned(account, rewardToken);

        // Also exercise a direct public entry `earned` by calling it again and verifying stability
        uint256 earnedAgain = c.earned(account, rewardToken);

        assert(earnedAfter == claimableBefore && earnedAgain == earnedAfter);
    }
}

