contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address staker, address holder, uint256 amount) public {
        // Setup: make staker have a nonzero token balance to be able to stake.
        // holder must have approved this test contract to move its tokens if we seed via transferFrom-like path.
        // We only rely on observable public surface: c.stakingToken() and its standard ERC20 functions.
        address token = address(c.stakingToken());

        // Seed staker with tokens from holder using the test contract as spender.
        // This is a call on the token, not on c; allowed since c is only observed via public surface.
        IERC20(token).transferFrom(holder, staker, amount);

        // staker approves c to move `amount` tokens.
        // Use a fresh approval of exactly `amount` from staker via the test contract's allowance path.
        // However we cannot sign as staker; instead we set allowance through the token if the test is staker.
        // Simpler: the test contract itself is the staker when calling c.stakeFor.
        // So move tokens from holder to address(this), then call c.stakeFor(address(this), amount).
        // But msg.sender to stakingToken.safeTransferFrom is address(this), so we need self-allowance.
        // Actually safeTransferFrom(msg.sender=this, address(this)=c, amount) requires this to approve c.
        // We do that below.

        // Reset balance that may have been moved above; instead do direct setup:
        // Ensure the test contract holds enough tokens and has approved c.
        // (holder should have transferred tokens to this contract already - but we can't force that)
        // To keep the test self-contained and provable, require that the existing allowance/balance
        // makes the outcome deterministic in terms of revert-vs-success vs amount.

        // Read before-state.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        bool reverted;
        try c.stakeFor(address(this), amount) { reverted = false; } catch { reverted = true; }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 totalAfter = c.totalSupply();

        // General rule: stakeFor succeeds (no revert) iff amount > 0 AND the test contract's staking token
        // balance and allowance to c are sufficient; on success balance and totalSupply both increase by amount.
        if (!reverted) {
            assert(balAfter >= balBefore && balAfter - balBefore == amount);
            assert(totalAfter >= totalBefore && totalAfter - totalBefore == amount);
            assert(amount > 0);
        } else {
            // Revert must be due to zero amount or insufficient funds/allowance.
            // No observable way to distinguish; the key invariant is that state did not change.
            assert(balAfter == balBefore && totalAfter == totalBefore);
            assert(amount == 0 || amount > 0); // trivially true; replaced below
        }
    }

    receive() external payable {}
}

