contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount) public {
        require(amount > 0, "amount must be positive");
        require(staker != address(0), "staker must be non-zero");

        // Ensure c has enough allowance/balance? The test contract is the owner of c.
        // We cannot mint stakingToken here. Instead, drive c via stakeFor if possible,
        // but stakingToken is an IERC20 whose address is known only through c.stakingToken().
        // We cannot call arbitrary token methods without declaring IERC20, but we may use
        // the public surface of c only. The only way to change totalSupply via c is:
        // stake / stakeAll / stakeFor / migrateStake, which require token transfers.
        // Since we cannot mint, we cannot reliably stake. However the rule can be
        // stated over any state: totalSupply() returns a value. If no stake happens,
        // the sum of balances is 0, so totalSupply must be 0.

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceStakerBefore = c.balanceOf(staker);

        // The only call we make is a view call to totalSupply. It always completes (view, no revert).
        uint256 supplyAfter = c.totalSupply();

        // General rule: totalSupply is invariant across a pure view call, and
        // it must be at least the observed balance of any single account, and
        // if no state change occurred (no state-changing calls in this run), it equals the initial supply.
        assert(supplyAfter == supplyBefore);
        assert(supplyAfter >= balanceStakerBefore);
    }
}

