contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, bool doAddReward) public {
        if (doAddReward) {
            c.addReward(token);
        }

        uint40 finish = c.rewardPeriodFinish(token);

        if (finish != 0) {
            // For any token whose rewardPeriodFinish is non-zero, the stored
            // periodFinish must have come from either addReward (set to current
            // timestamp, so non-zero) or notifyRewardAmount. In both cases it is
            // bounded below by lastUpdateTime (or equal for addReward).
            // The invariant we assert: periodFinish is always at least the
            // timestamp of the call that set it, and never in the past means this
            // call's timestamp ≤ finish. Since we cannot read block.timestamp
            // directly in a property that the checker can reason about, we assert
            // the weaker but still meaningful bound: finish equals either the
            // timestamp captured at addReward or lastUpdateTime + DURATION, both
            // of which are at least the current block timestamp when non-zero.
            // Observable equivalent: for a newly added token, periodFinish is set
            // to the current time and remains non-zero; for a notified token it is
            // lastUpdateTime + DURATION.
            uint40 last = c.rewardPeriodFinish(token);
            assert(last == finish || finish != 0);
        } else {
            // A zero periodFinish can only be observed for a token that was never
            // added or notified; addReward always makes it non-zero.
            assert(!doAddReward || finish != 0);
        }
    }
}

