contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, uint256 amount) public {
        address distributor = c.rewardDistributor();
        require(distributor == address(this), "test must be distributor");

        // Ensure the token is a known reward token before the deciding call.
        bool tokenAdded;
        try c.addReward(token) { tokenAdded = true; } catch { tokenAdded = false; }

        // Before the deciding call, the token may or may not be known.
        bool lastUpdateTimeBeforePositive = true;
        if (tokenAdded) {
            lastUpdateTimeBeforePositive = true;
        } else {
            // addReward may have reverted either because the token already exists
            // (in which case it is known) or because the caller is not the owner.
            // We cannot distinguish those from outside, so we only assert the
            // well-defined case where addReward succeeded.
        }

        bool reverted;
        try c.notifyRewardAmount(token, amount) { reverted = false; } catch { reverted = true; }

        // General rule: when the caller is the reward distributor and the token
        // has successfully been added with amount > 0, notifyRewardAmount must
        // not revert. If amount == 0 it must revert. If addReward failed, we
        // cannot conclude anything about whether the token was already known,
        // so the property is only required for the successful-add case.
        if (tokenAdded && distributor == address(this)) {
            if (amount > 0) {
                assert(!reverted);
            } else {
                assert(reverted);
            }
        } else {
            assert(true);
        }
    }
}

