contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public {
        address owner = c.owner();
        bool wasKnown = c.rewardPeriodFinish(token) != 0;
        uint256 lenBefore = 0;
        uint256 i = 0;
        while (true) {
            try c.rewardTokens(i) returns (address t) {
                i++;
                lenBefore++;
            } catch {
                break;
            }
        }
        bool reverted;
        try c.addReward(token) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 lenAfter = 0;
        uint256 j = 0;
        while (true) {
            try c.rewardTokens(j) returns (address t) {
                j++;
                lenAfter++;
            } catch {
                break;
            }
        }
        if (reverted) {
            assert(lenAfter == lenBefore);
        } else {
            assert(!wasKnown);
            assert(lenAfter == lenBefore + 1);
        }
    }
}

